import React from "react";
import "../Style/TaskCard.css"
import completeIcon from "./assets/CheckCircle.png";
import updateIcon from "./assets/Group 127.png";
import deleteIcon from "./assets/Group 130.png";

function TaskCard({ task, onComplete, onDelete }) {
  return (
    <div className="task-card">
      <div className="task-info">
        <h2>{task.title}</h2>
        <p className="description">{task.description}</p>
        <p className="date">Start date : {task.startDate}</p>
      </div>
      <div className="icons">
        <div className="task-actions">
          <button className="btn complete" onClick={onComplete}>
            <img src={completeIcon} alt="Complete" />
          </button>
          <button className="btn edit">
            <img src={updateIcon} alt="Edit" />
          </button>
          <button className="btn delete" onClick={onDelete}>
            <img src={deleteIcon} alt="Delete" />
          </button>
        </div>
      </div>
    </div>
  );
}

export default TaskCard;
